#version 300 es

#define HLSLCC_ENABLE_UNIFORM_BUFFERS 0
#if HLSLCC_ENABLE_UNIFORM_BUFFERS
#define UNITY_UNIFORM
#else
#define UNITY_UNIFORM uniform
#endif
#define UNITY_SUPPORTS_UNIFORM_LOCATION 0
#if UNITY_SUPPORTS_UNIFORM_LOCATION
#define UNITY_LOCATION(x) layout(location = x)
#define UNITY_BINDING(x) layout(binding = x, std140)
#else
#define UNITY_LOCATION(x)
#define UNITY_BINDING(x) layout(std140)
#endif
uniform 	vec4 hlslcc_mtx4x4unity_ObjectToWorld[4];
uniform 	vec4 hlslcc_mtx4x4unity_MatrixVP[4];
in highp vec4 in_POSITION0;
out highp vec3 vs_TEXCOORD0;
vec4 u_xlat0;
vec4 u_xlat1;
void main()
{
    u_xlat0 = in_POSITION0.yyyy * hlslcc_mtx4x4unity_ObjectToWorld[1];
    u_xlat0 = hlslcc_mtx4x4unity_ObjectToWorld[0] * in_POSITION0.xxxx + u_xlat0;
    u_xlat0 = hlslcc_mtx4x4unity_ObjectToWorld[2] * in_POSITION0.zzzz + u_xlat0;
    u_xlat0 = u_xlat0 + hlslcc_mtx4x4unity_ObjectToWorld[3];
    u_xlat1 = u_xlat0.yyyy * hlslcc_mtx4x4unity_MatrixVP[1];
    u_xlat1 = hlslcc_mtx4x4unity_MatrixVP[0] * u_xlat0.xxxx + u_xlat1;
    u_xlat1 = hlslcc_mtx4x4unity_MatrixVP[2] * u_xlat0.zzzz + u_xlat1;
    gl_Position = hlslcc_mtx4x4unity_MatrixVP[3] * u_xlat0.wwww + u_xlat1;
    vs_TEXCOORD0.xyz = in_POSITION0.xyz;
    return;
}


#version 300 es

precision highp float;
precision highp int;
#define HLSLCC_ENABLE_UNIFORM_BUFFERS 0
#if HLSLCC_ENABLE_UNIFORM_BUFFERS
#define UNITY_UNIFORM
#else
#define UNITY_UNIFORM uniform
#endif
#define UNITY_SUPPORTS_UNIFORM_LOCATION 0
#if UNITY_SUPPORTS_UNIFORM_LOCATION
#define UNITY_LOCATION(x) layout(location = x)
#define UNITY_BINDING(x) layout(binding = x, std140)
#else
#define UNITY_LOCATION(x)
#define UNITY_BINDING(x) layout(std140)
#endif
uniform 	vec4 _WorldSpaceLightPos0;
uniform 	mediump vec4 _SunDiscColor;
uniform 	float _SunDiscMultiplier;
uniform 	float _SunDiscExponent;
uniform 	mediump vec4 _SunHaloColor;
uniform 	float _SunHaloExponent;
uniform 	float _SunHaloContribution;
uniform 	mediump vec4 _HorizonLineColor;
uniform 	float _HorizonLineExponent;
uniform 	float _HorizonLineContribution;
uniform 	mediump vec4 _SkyGradientTop;
uniform 	mediump vec4 _SkyGradientBottom;
uniform 	float _SkyGradientExponent;
in highp  vec3 vs_TEXCOORD0;
layout(location = 0) out mediump vec4 SV_Target0;
vec3 u_xlat0;
bool u_xlatb0;
vec3 u_xlat1;
vec3 u_xlat2;
vec3 u_xlat3;
float u_xlat6;
float u_xlat9;
float u_xlat10;
void main()
{
    u_xlat0.x = dot(_WorldSpaceLightPos0.xyz, _WorldSpaceLightPos0.xyz);
    u_xlat3.x = inversesqrt(u_xlat0.x);
    u_xlatb0 = 9.99999975e-05<u_xlat0.x;
    u_xlat3.xyz = u_xlat3.xxx * _WorldSpaceLightPos0.xyz;
    u_xlat0.xyz = (bool(u_xlatb0)) ? u_xlat3.xyz : vec3(0.0, 0.44721359, 0.89442718);
    u_xlat9 = dot(vs_TEXCOORD0.xyz, vs_TEXCOORD0.xyz);
    u_xlat9 = inversesqrt(u_xlat9);
    u_xlat1.xyz = vec3(u_xlat9) * vs_TEXCOORD0.xyz;
    u_xlat0.x = dot(u_xlat1.xyz, u_xlat0.xyz);
    u_xlat0.x = clamp(u_xlat0.x, 0.0, 1.0);
    u_xlat0.x = log2(u_xlat0.x);
    u_xlat3.x = max(_SunHaloExponent, 9.99999975e-05);
    u_xlat3.x = u_xlat0.x * u_xlat3.x;
    u_xlat3.x = exp2(u_xlat3.x);
    u_xlat3.x = u_xlat3.x * _SunHaloContribution;
    u_xlat3.x = clamp(u_xlat3.x, 0.0, 1.0);
    u_xlat6 = u_xlat1.y;
    u_xlat6 = clamp(u_xlat6, 0.0, 1.0);
    u_xlat9 = -abs(u_xlat1.y) + 1.0;
    u_xlat9 = max(u_xlat9, 0.0);
    u_xlat9 = log2(u_xlat9);
    u_xlat6 = log2(u_xlat6);
    u_xlat1.x = max(_SkyGradientExponent, 9.99999975e-05);
    u_xlat1.x = float(1.0) / u_xlat1.x;
    u_xlat6 = u_xlat6 * u_xlat1.x;
    u_xlat6 = exp2(u_xlat6);
    u_xlat1.xyz = _SkyGradientTop.xyz + (-_SkyGradientBottom.xyz);
    u_xlat1.xyz = vec3(u_xlat6) * u_xlat1.xyz + _SkyGradientBottom.xyz;
    u_xlat2.xyz = (-u_xlat1.xyz) + _SunHaloColor.xyz;
    u_xlat1.xyz = u_xlat3.xxx * u_xlat2.xyz + u_xlat1.xyz;
    u_xlat2.xyz = (-u_xlat1.xyz) + _HorizonLineColor.xyz;
    u_xlat3.x = max(_HorizonLineExponent, 9.99999975e-05);
    u_xlat3.x = u_xlat9 * u_xlat3.x;
    u_xlat3.x = exp2(u_xlat3.x);
    u_xlat3.x = u_xlat3.x * _HorizonLineContribution;
    u_xlat3.x = clamp(u_xlat3.x, 0.0, 1.0);
    u_xlat3.xyz = u_xlat3.xxx * u_xlat2.xyz + u_xlat1.xyz;
    u_xlat1.xyz = (-u_xlat3.xyz) + _SunDiscColor.xyz;
    u_xlat10 = max(_SunDiscExponent, 9.99999975e-05);
    u_xlat0.x = u_xlat0.x * u_xlat10;
    u_xlat0.x = exp2(u_xlat0.x);
    u_xlat0.x = u_xlat0.x * _SunDiscMultiplier;
    u_xlat0.x = clamp(u_xlat0.x, 0.0, 1.0);
    u_xlat0.xyz = u_xlat0.xxx * u_xlat1.xyz + u_xlat3.xyz;
    SV_Target0.xyz = u_xlat0.xyz;
    SV_Target0.w = 1.0;
    return;
}
